package com.pizzalab;
import com.pizzalab.dto.*; import com.pizzalab.model.OrderStatus; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.web.client.TestRestTemplate; import org.springframework.boot.test.web.server.LocalServerPort; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import java.time.LocalDate; import java.time.ZoneId; import java.util.List; import static org.junit.jupiter.api.Assertions.*;
/** Integración HTTP + SQLite + Batch sobre una base de pruebas separada. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class PizzaLabIntegrationTest {
 @Autowired TestRestTemplate http; @Autowired JdbcTemplate jdbc; @LocalServerPort int port;
 private String url(String path){return "http://localhost:"+port+path;}
 @BeforeEach void clean(){jdbc.update("DELETE FROM sales_reports");jdbc.update("DELETE FROM order_lines");jdbc.update("DELETE FROM orders");}
 @Test void creaPedidoCambiaEstadoYGeneraReporte(){CreateOrderRequest request=new CreateOrderRequest(List.of(new OrderItemRequest(1,2)));ResponseEntity<OrderResponse> created=http.postForEntity(url("/api/orders"),request,OrderResponse.class);assertEquals(HttpStatus.CREATED,created.getStatusCode());assertEquals(25800,created.getBody().totalCents());http.exchange(url("/api/orders/"+created.getBody().id()+"/status"),HttpMethod.PATCH,new HttpEntity<>(new StatusRequest(OrderStatus.EN_PREPARACION)),OrderResponse.class);String today=LocalDate.now().toString();ResponseEntity<SalesReportResponse> report=http.postForEntity(url("/api/batch/sales-report?date="+today),null,SalesReportResponse.class);assertEquals(HttpStatus.OK,report.getStatusCode());assertEquals(1,report.getBody().orderCount());assertEquals(25800,report.getBody().totalCents());}
 @Test void batchVacioGeneraReporteCeroYRutaInexistenteEs404(){String day="2000-01-01";ResponseEntity<SalesReportResponse> report=http.postForEntity(url("/api/batch/sales-report?date="+day),null,SalesReportResponse.class);assertEquals(0,report.getBody().orderCount());ResponseEntity<String> missing=http.getForEntity(url("/api/reports/sales?date=2001-01-01"),String.class);assertEquals(HttpStatus.NOT_FOUND,missing.getStatusCode());}
 @Test void analyticsYBatchCubrenUnIntervaloPersistido(){String from="2000-01-01";String to="2000-01-02";ResponseEntity<String> analytics=http.getForEntity(url("/api/analytics/sales?from="+from+"&to="+to),String.class);assertEquals(HttpStatus.OK,analytics.getStatusCode());assertTrue(analytics.getBody().contains("\"orderCount\":0"));ResponseEntity<String> reports=http.postForEntity(url("/api/batch/sales-report/range?from="+from+"&to="+to),null,String.class);assertEquals(HttpStatus.OK,reports.getStatusCode());assertTrue(reports.getBody().contains("\"date\":\"2000-01-01\""));assertTrue(reports.getBody().contains("\"date\":\"2000-01-02\""));}
 @Test void analyticsAgregaPedidosRealesYPermiteElOrigenAngular(){http.postForEntity(url("/api/orders"),new CreateOrderRequest(List.of(new OrderItemRequest(1,2))),OrderResponse.class);String today=LocalDate.now(ZoneId.of("America/Mexico_City")).toString();HttpHeaders headers=new HttpHeaders();headers.setOrigin("http://localhost:4200");ResponseEntity<String> response=http.exchange(url("/api/analytics/sales?from="+today+"&to="+today),HttpMethod.GET,new HttpEntity<>(headers),String.class);assertEquals(HttpStatus.OK,response.getStatusCode());assertEquals("http://localhost:4200",response.getHeaders().getFirst(HttpHeaders.ACCESS_CONTROL_ALLOW_ORIGIN));assertTrue(response.getBody().contains("\"totalRevenueCents\":25800"));assertTrue(response.getBody().contains("\"bestSellingProduct\":\"Margarita\""));assertTrue(response.getBody().contains("\"RECIBIDO\":1"));}
}
